<template>
  <div class="weather-container" v-click-outside="closeDropdown">

    <!-- Кастомный выпадающий список городов -->
    <div class="city-wrap">
      <div class="city-btn" @click="dropdownOpen = !dropdownOpen" :class="{ 'city-btn--open': dropdownOpen }">
        <v-icon size="14" color="#6366f1">mdi-map-marker</v-icon>
        <span class="city-name">{{ currentCityLabel }}</span>
        <v-icon size="14" color="#94a3b8" class="city-chevron">mdi-chevron-down</v-icon>
      </div>

      <transition name="dropdown">
        <div class="city-dropdown" v-if="dropdownOpen">
          <div class="city-dropdown-inner">
            <div
                v-for="city in cities"
                :key="city.q"
                class="city-option"
                :class="{ 'city-option--active': city.q === selectedCity }"
                @click="selectCity(city)"
            >
              <v-icon size="12" color="#6366f1" v-if="city.q === selectedCity">mdi-check</v-icon>
              <span>{{ city.label }}</span>
            </div>
          </div>
        </div>
      </transition>
    </div>

    <!-- Погода -->
    <div class="weather">
      <img v-if="weatherImg" class="weather-icon" :src="weatherImg" alt="" />
      <span class="weather-temp" :style="{ color: weatherTempColor || '#1e293b' }">{{ weatherTemp }}</span>
    </div>

    <!-- Разделитель -->
    <div class="sep"></div>

    <!-- Курс -->
    <div class="curr-wrap" v-click-outside="closeCurrDropdown">
      <div class="curr-btn" @click="currDropdownOpen = !currDropdownOpen" :class="{ 'curr-btn--open': currDropdownOpen }">
        <span class="curr-symbol">{{ selectedCurrency.symbol }}</span>
        <span class="curr-val" :class="{ 'is-error': currencyIsUnload }">{{ currencyInfo }}</span>
        <span class="currency-nbu">НБУ</span>
        <v-icon size="14" color="#94a3b8" class="curr-chevron">mdi-chevron-down</v-icon>
      </div>

      <transition name="dropdown">
        <div class="city-dropdown" v-if="currDropdownOpen" style="left: auto; right: 0;">
          <div class="city-dropdown-inner">
            <div
                v-for="curr in currencies"
                :key="curr.code"
                class="city-option"
                :class="{ 'city-option--active': curr.code === selectedCurrency.code }"
                @click="selectCurrency(curr)"
            >
              <v-icon size="12" color="#6366f1" v-if="curr.code === selectedCurrency.code">mdi-check</v-icon>
              <span class="curr-option-symbol">{{ curr.symbol }}</span>
              <span>{{ curr.label }}</span>
            </div>
          </div>
        </div>
      </transition>
    </div>

  </div>
</template>

<script>
import $ from 'jquery'

export default {
  name: 'WeatherComponent',

  directives: {
    'click-outside': {
      mounted(el, binding) {
        el._clickOutside = (e) => { if (!el.contains(e.target)) binding.value() }
        document.addEventListener('click', el._clickOutside)
      },
      unmounted(el) {
        document.removeEventListener('click', el._clickOutside)
      },
    },
  },

  data() {
    return {
      selectedCity:  'Kyiv',
      dropdownOpen:  false,
      cities: [
        { label: 'Киев',             q: 'Kyiv'            },
        { label: 'Харьков',          q: 'Kharkiv'         },
        { label: 'Одесса',           q: 'Odessa'          },
        { label: 'Днепр',            q: 'Dnipro'          },
        { label: 'Запорожье',        q: 'Zaporizhzhia'    },
        { label: 'Львов',            q: 'Lviv'            },
        { label: 'Кривой Рог',       q: 'Kryvyi Rih'      },
        { label: 'Николаев',         q: 'Mykolaiv'        },
        { label: 'Мариуполь',        q: 'Mariupol'        },
        { label: 'Луганск',          q: 'Luhansk'         },
        { label: 'Винница',          q: 'Vinnytsia'       },
        { label: 'Херсон',           q: 'Kherson'         },
        { label: 'Полтава',          q: 'Poltava'         },
        { label: 'Чернигов',         q: 'Chernihiv'       },
        { label: 'Черкассы',         q: 'Cherkasy'        },
        { label: 'Сумы',             q: 'Sumy'            },
        { label: 'Житомир',          q: 'Zhytomyr'        },
        { label: 'Ровно',            q: 'Rivne'           },
        { label: 'Ивано-Франковск',  q: 'Ivano-Frankivsk' },
        { label: 'Тернополь',        q: 'Ternopil'        },
        { label: 'Хмельницкий',      q: 'Khmelnytskyi'    },
        { label: 'Ужгород',          q: 'Uzhhorod'        },
        { label: 'Черновцы',         q: 'Chernivtsi'      },
        { label: 'Луцк',             q: 'Lutsk'           },
        { label: 'Кропивницкий',     q: 'Kropyvnytskyi'   },
      ],
      weatherTemp:      '',
      weatherImg:       '',
      weatherTempColor: '',
      currencyInfo:     '',
      weatherIsUnload:  false,
      currencyIsUnload: false,
      currDropdownOpen: false,
      selectedCurrency: { code: 'USD', label: 'Доллар США', symbol: '$', txt: 'Долар США' },
      currencies: [
        { code: 'USD', label: 'Доллар США',  symbol: '$', txt: 'Долар США'  },
        { code: 'EUR', label: 'Евро',         symbol: '€', txt: 'Євро'       },
        { code: 'CNY', label: 'Юань',         symbol: '¥', txt: 'Юань Женьміньбі' },
      ],
    }
  },

  computed: {
    currentCityLabel() {
      const city = this.cities.find(c => c.q === this.selectedCity)
      return city ? city.label : '—'
    },
  },

  mounted() {
    this.showWeather(this.selectedCity)
    this.showCurrency()

    setInterval(() => {
      this.showWeather(this.selectedCity)
      this.showCurrency()
    }, 1800000)
  },

  methods: {
    selectCity(city) {
      this.selectedCity = city.q
      this.dropdownOpen = false
      this.showWeather(city.q)
    },

    closeDropdown() {
      this.dropdownOpen = false
    },

    closeCurrDropdown() {
      this.currDropdownOpen = false
    },

    selectCurrency(curr) {
      this.selectedCurrency = curr
      this.currDropdownOpen = false
      this.showCurrency()
    },

    showWeather(location) {
      $.ajax({
        url:         `https://api.weatherapi.com/v1/current.json?key=5f6ae58e18e644888bf182855242904&q=${location}`,
        method:      'GET',
        crossDomain: true,
        dataType:    'json',
        success: (data) => {
          const temp = data.current.temp_c
          this.weatherTemp = `${temp}°C`
          this.weatherImg  = data.current.condition.icon

          if (parseFloat(temp) >= 35)    this.weatherTempColor = '#f97316'
          else if (parseFloat(temp) < 0) this.weatherTempColor = '#3b82f6'
          else                           this.weatherTempColor = '#1e293b'
        },
        error: () => {
          this.weatherIsUnload = true
        },
      })
    },

    showCurrency() {
      $.ajax({
        url:         'https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?json',
        method:      'GET',
        crossDomain: true,
        dataType:    'json',
        success: (data) => {
          const curr = data.find(f => f.txt === this.selectedCurrency.txt)
          this.currencyInfo = curr ? curr.rate : '—'
        },
        error: () => {
          this.currencyIsUnload = true
          this.currencyInfo     = 'Ошибка'
        },
      })
    },
  },
}
</script>

